package com.civicpulse.service; import com.civicpulse.repository.UserRepository; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import java.util.*;
@Service public class CurrentUserService {private final UserRepository users; public CurrentUserService(UserRepository users){this.users=users;} public com.civicpulse.entity.User get(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null)throw new IllegalStateException("Authentication required");return users.findById(UUID.fromString(a.getName())).orElseThrow();}}
